describe('RF-D01 isolated inert source contract - exact approved 48 negative vectors', () => {
  it.each(negativeVectors)('$id - $diagnostic', (vector) => {
    const input = patch(fixture(vector.deriveFrom), vector.patches);
    const before = JSON.stringify(input);
    const result = inspectFinanceBudgetReserveSourceContract(input);
    expect(
      ['INERT_REJECTED', 'INERT_MISSING_INPUT'],
      JSON.stringify(result),
    ).toContain(result.status);
    expect(result.productionAuthority).toBe(false);
    expect(result.sourceAdmitted).toBe(false);
    expect(result.actualSourceObservation).toBe('NOT_CONSTRUCTED');
    expect(result.actualCacheObservation).toBe('NOT_CONSTRUCTED');
    expect(result).not.toHaveProperty('balances');
    expect(result).not.toHaveProperty('effect');
    expect(result).not.toHaveProperty('reservationRef');
    expect(result).not.toHaveProperty('cutoff');
    if (
      result.status === 'INERT_REJECTED' ||
      result.status === 'INERT_MISSING_INPUT'
    ) {
      expect(result.reason.length).toBeGreaterThan(0);
      expect(result.diagnostic.length).toBeGreaterThan(0);
    }
    expect(JSON.stringify(input)).toBe(before);
  });
});
